 "content": "from src.billing.tax import invoice_tax, line_total


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_invoice_tax_rounds_subtotal_once():
    lines = [{"quantity": 1, "unit_cents": 10}, {"quantity": 1, "unit_cents": 10}]
    assert invoice_tax(lines, 0.05, "US-TX") == 1


def test_invoice_tax_quebec_rounds_per_line():
    lines = [{"quantity": 1, "unit_cents": 10}, {"quantity": 1, "unit_cents": 10}]
    assert invoice_tax(lines, 0.05, "CA-QC") == 0


def test_invoice_tax_rounds_half_even():
    assert invoice_tax([{"quantity": 1, "unit_cents": 50}], 0.05, "US-TX") == 2
    assert invoice_tax([{"quantity": 1, "unit_cents": 70}], 0.05, "US-TX") == 4


def test_invoice_tax_exempt_is_zero():
    assert invoice_tax([{"quantity": 3, "unit_cents": 999}], 0, "US-TX") == 0
    assert invoice_tax([], 0.0825, "CA-QC") == 0
